package facts

import (
	"os"
	"reflect"
	"strings"
	"testing"
)

// TestGeneratedHeader pins the markers (do not edit, do not modify,
// @generated, <auto-generated, any case), the comment-only header and the
// 20-line limit.
func TestGeneratedHeader(t *testing.T) {
	comments := func(n int) string { return strings.Repeat("// comment\n", n) }
	cases := []struct {
		name    string
		content string
		want    bool
	}{
		{"go marker on line 1", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n", true},
		{"satelle header", "// satelle-owned: pi extension — written by `satelle agents install pi`.\n// Do not edit: `satelle init` rewrites it from the binary when it drifts.\nimport x from \"y\";\n", true},
		{"protoc python after coding line", "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\nimport x\n", true},
		{"auto-generated with BOM and CRLF", "\xef\xbb\xbf// <auto-generated>\r\n//     This code was generated by a tool.\r\n// </auto-generated>\r\nusing System;\r\n", true},
		{"@generated", "// @generated\nexport const x = 1;\n", true},
		{"block comment", "/*\n * Code generated by x. DO NOT EDIT.\n */\npackage x\n", true},
		{"html do not modify", "<!-- do not modify -->\n<html></html>\n", true},
		{"sql do not edit", "-- DO NOT EDIT\nselect 1;\n", true},
		{"marker on line 20", comments(19) + "// DO NOT EDIT\npackage x\n", true},

		{"marker on line 21", comments(20) + "// DO NOT EDIT\npackage x\n", false},
		{"marker after package", "package x\n\n// DO NOT EDIT\n", false},
		{"marker in a string", "const s = \"do not edit\"\n", false},
		{"generated alone", "// generated by hand\npackage x\n", false},
		{"binary", "// DO NOT EDIT\x00\n", false},
		{"empty", "", false},
	}
	for _, c := range cases {
		if got := GeneratedHeader([]byte(c.content)); got != c.want {
			t.Errorf("%s: GeneratedHeader = %v, want %v", c.name, got, c.want)
		}
	}
}

// TestWithClass pins that the added class keeps Class order and appears once.
func TestWithClass(t *testing.T) {
	cases := []struct {
		in, want []Class
	}{
		{[]Class{ClassDocs, ClassTest}, []Class{ClassDocs, ClassGenerated, ClassTest}},
		{[]Class{ClassGenerated}, []Class{ClassGenerated}},
		{nil, []Class{ClassGenerated}},
	}
	for _, c := range cases {
		if got := withClass(c.in, ClassGenerated); !reflect.DeepEqual(got, c.want) {
			t.Errorf("withClass(%v, generated) = %v, want %v", c.in, got, c.want)
		}
	}
}

// TestShellShebang pins which first lines make an extensionless file a Shell
// script: a shell interpreter by path or through env, arguments tolerated,
// BOM and CRLF stripped; nothing else.
func TestShellShebang(t *testing.T) {
	for _, tt := range []struct {
		content string
		want    bool
	}{
		{"#!/bin/sh\ntrue\n", true},
		{"#!/bin/bash\n", true},
		{"#!/bin/dash\n", true},
		{"#!/bin/zsh\n", true},
		{"#!/bin/ksh\n", true},
		{"#!/usr/bin/env bash\n", true},
		{"#!/usr/bin/env sh\n", true},
		{"#! /bin/bash -e\n", true},
		{"#!/usr/bin/env -S bash -e\n", true},
		{"#!/usr/bin/env LC_ALL=C bash\n", true},
		{"\xef\xbb\xbf#!/bin/sh\r\necho\r\n", true},
		{"#!/usr/bin/env python3\n", false},
		{"#!/usr/bin/env node\n", false},
		{"#!/usr/bin/python\n", false},
		{"#!/bin/fish\n", false},
		{"#!/usr/bin/env\n", false},
		{"echo hi\n", false},
		{"# !/bin/sh\n", false},
		{"\n#!/bin/sh\n", false},
		{"", false},
		{"#!/bin/bash\n\x00binary", false},
	} {
		if got := ShellShebang([]byte(tt.content)); got != tt.want {
			t.Errorf("ShellShebang(%q) = %v, want %v", tt.content, got, tt.want)
		}
	}
}

// TestReadmeDocumentsShebangs pins the README to the shebang rule: the Which
// files count section names it with examples and every shell interpreter, the
// Plan file section and the Tests row mention it.
func TestReadmeDocumentsShebangs(t *testing.T) {
	data, err := os.ReadFile("../../README.md")
	if err != nil {
		t.Fatal(err)
	}
	s := string(data)
	section := func(heading string) string {
		i := strings.Index(s, "\n"+heading+"\n")
		if i < 0 {
			t.Fatalf("README has no %q section", heading)
		}
		rest := s[i+len(heading)+2:]
		level := strings.Index(heading, " ")
		for j := 0; j < len(rest); j++ {
			if (j == 0 || rest[j-1] == '\n') && strings.HasPrefix(rest[j:], "#") {
				if len(rest[j:])-len(strings.TrimLeft(rest[j:], "#")) <= level {
					return rest[:j]
				}
			}
		}
		return rest
	}
	which := section("#### Which files count")
	wants := []string{"shebang", "`#!/bin/bash`", "`#!/usr/bin/env bash`", "`python3`", "`node`"}
	for _, sh := range shellInterpreters {
		wants = append(wants, "`"+sh+"`")
	}
	for _, w := range wants {
		if !strings.Contains(which, w) {
			t.Errorf("README Which files count lacks %s", w)
		}
	}
	if !strings.Contains(section("### Plan file"), "shebang") {
		t.Error("README Plan file section lacks shebang")
	}
	found := false
	for _, line := range strings.Split(s, "\n") {
		if strings.HasPrefix(line, "| Tests |") {
			found = strings.Contains(line, "shebang")
		}
	}
	if !found {
		t.Error("README Tests row lacks shebang")
	}
}
